public struct BridgeMark: View {
    public var size: CGFloat = 40
    public init(size: CGFloat = 40) { self.size = size }

    public var body: some View {
        Canvas { context, bounds in
            let s = min(bounds.width, bounds.height) / Self.side
            let transform = CGAffineTransform(scaleX: s, y: s)
            for layer in Self.layers {
                let path = layer.path.applying(transform)
                if let fill = layer.fill { context.fill(path, with: .color(fill)) }
                if let stroke = layer.stroke {
