extension Path {
    /// SVG's elliptical arc, which SwiftUI has no direct equivalent for.
    ///
    /// Implemented by centre-parameterisation per the SVG specification, appendix
    /// F.6. The prototype uses it for the storage cylinder and the chain links.
    mutating func addSVGArc(from: CGPoint, to: CGPoint, rx: CGFloat, ry: CGFloat,
                            rotation: CGFloat, largeArc: Bool, sweep: Bool) {
        guard rx != 0, ry != 0 else { addLine(to: to); return }
        let phi = rotation * .pi / 180
        let dx2 = (from.x - to.x) / 2, dy2 = (from.y - to.y) / 2
        let x1 =  cos(phi) * dx2 + sin(phi) * dy2
        let y1 = -sin(phi) * dx2 + cos(phi) * dy2
        var rx = abs(rx), ry = abs(ry)
        let lambda = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry)
        if lambda > 1 { rx *= sqrt(lambda); ry *= sqrt(lambda) }
        let sign: CGFloat = largeArc == sweep ? -1 : 1
        let num = max(0, rx*rx * ry*ry - rx*rx * y1*y1 - ry*ry * x1*x1)
        let den = rx*rx * y1*y1 + ry*ry * x1*x1
        let coef = sign * sqrt(den == 0 ? 0 : num / den)
        let cx1 =  coef * rx * y1 / ry
        let cy1 = -coef * ry * x1 / rx
        let cx = cos(phi) * cx1 - sin(phi) * cy1 + (from.x + to.x) / 2
        let cy = sin(phi) * cx1 + cos(phi) * cy1 + (from.y + to.y) / 2
        let start = atan2((y1 - cy1) / ry, (x1 - cx1) / rx)
        let end   = atan2((-y1 - cy1) / ry, (-x1 - cx1) / rx)
        var delta = end - start
        if !sweep && delta > 0 { delta -= 2 * .pi }
        if sweep && delta < 0 { delta += 2 * .pi }
        var transform = CGAffineTransform(translationX: cx, y: cy)
            .rotated(by: phi)
            .scaledBy(x: rx, y: ry)
        addArc(center: .zero, radius: 1, startAngle: .radians(start),
               endAngle: .radians(start + delta), clockwise: delta < 0,
               transform: transform)
    }
}
